def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]

    try:
        change_ratio = (new_value - old_value) / old_value
    except ZeroDivisionError:
        return None

    percentage_change = change_ratio * 100
    return {
        "value": percentage_change,
        "trace": {
            "old_value_2017": old_value,
            "new_value_2018": new_value,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
